# Helpers for SVG charts
def date_to_num(d): return d.toordinal()

def line_chart(rows):
    W,H=1100,520; ml,mr,mt,mb=72,38,44,68
    xs=[date_to_num(r['date']) for r in rows]; ys=[r['price'] for r in rows]
    xmin,xmax=min(xs),max(xs); ymin=0; ymax=140
    def X(d): return ml+(date_to_num(d)-xmin)/(xmax-xmin)*(W-ml-mr)
    def Y(v): return mt+(ymax-v)/(ymax-ymin)*(H-mt-mb)
    pts=' '.join(f"{X(r['date']):.2f},{Y(r['price']):.2f}" for r in rows)
    out=[]
    out.append(f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Monthly crude oil price line chart from 1970 to 2026">')
    out.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    # grid y
    for val in range(0,141,20):
        y=Y(val)
        out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="#e6edf3"/>')
        out.append(f'<text x="{ml-10}" y="{y+4:.2f}" text-anchor="end" class="axis">${val}</text>')
    # x ticks decades
    for yr in [1970,1980,1990,2000,2010,2020,2026]:
        x=X(date(yr,1,1) if yr<2026 else date(2026,3,1))
        out.append(f'<line x1="{x:.2f}" x2="{x:.2f}" y1="{mt}" y2="{H-mb}" stroke="#edf2f7"/>')
        out.append(f'<text x="{x:.2f}" y="{H-mb+28}" text-anchor="middle" class="axis">{yr}</text>')
    out.append(f'<polyline points="{pts}" fill="none" stroke="#0f5e9c" stroke-width="2.6" stroke-linejoin="round"/>')
