    <table>
      <thead><tr><th>Decade</th><th>Months</th><th>Mean</th><th>Median</th><th>Std. dev.</th><th>Min</th><th>Max</th><th>Range</th><th>First-to-last</th></tr></thead>
      <tbody>{decade_table}</tbody>
    </table>
    <h3>Regime interpretation</h3>
    <ul>
      <li><strong>1970s:</strong> mean price {fmt_price(decades[0]['mean'])}; first-to-last increase {fmt_pct(decades[0]['change_pct'])}, dominated by the 1974 step-change and late-1979 spike.</li>
