    out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{H-mb}" y2="{H-mb}" stroke="#334155"/><line x1="{ml}" x2="{ml}" y1="{mt}" y2="{H-mb}" stroke="#334155"/>')
    out.append(f'<text x="{W/2}" y="22" text-anchor="middle" class="legend">Bars show decade mean; whiskers show ±1 sample standard deviation</text>')
    out.append('</svg>')
    return ''.join(out)

def shock_chart(shocks):
    W,H=940,390; ml,mr,mt,mb=70,28,42,118
    vals=[s['value'] for s in shocks]; vmax=max(abs(v) for v in vals)*1.18
    def X(i): return ml+(i+0.5)*(W-ml-mr)/len(shocks)
    def Y(v): return mt+(vmax-v)/(2*vmax)*(H-mt-mb)
    zero=Y(0); barw=(W-ml-mr)/len(shocks)*0.52
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Largest absolute month-over-month price shocks">','<rect width="100%" height="100%" fill="#fff"/>']
    for val in [-30,-20,-10,0,10,20,30]:
        if abs(val)<=vmax:
            y=Y(val); out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="{="#334155" if val==0 else "#e6edf3"}"/><text x="{ml-8}" y="{y+4:.2f}" text-anchor="end" class="axis">{val:+}</text>')
    for i,s in enumerate(shocks):
        x=X(i); y=Y(s['value']); h=abs(y-zero); top=min(y,zero); color='#b91c1c' if s['value']<0 else '#047857'
        out.append(f'<rect x="{x-barw/2:.2f}" y="{top:.2f}" width="{barw:.2f}" height="{h:.2f}" rx="4" fill="{color}" opacity="0.86"/>')
        out.append(f'<text x="{x:.2f}" y="{(top-7 if s["value"]>0 else top+h+16):.2f}" text-anchor="middle" class="bar-label">{s["value"]:+.1f}</text>')
        out.append(f'<text x="{x:.2f}" y="{H-mb+25}" text-anchor="end" transform="rotate(-35 {x:.2f} {H-mb+25})" class="axis">{esc(s["label"])}</text>')
    out.append(f'<text x="{W/2}" y="24" text-anchor="middle" class="legend">Top absolute month-over-month changes, USD/bbl</text>')
    out.append('</svg>')
    return ''.join(out)

def histogram(prices):
    W,H=860,330; ml,mr,mt,mb=60,25,28,58
    binw=10; bins=list(range(0,151,10)); counts=[]
    for b in bins[:-1]: counts.append(sum(1 for p in prices if b <= p < b+binw))
    counts[-1]+=sum(1 for p in prices if p>=bins[-2]+binw)
    ymax=max(counts)*1.15
    def X(i): return ml+i*(W-ml-mr)/len(counts)
    def Y(v): return mt+(ymax-v)/ymax*(H-mt-mb)
    bw=(W-ml-mr)/len(counts)*0.82
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Histogram of monthly crude oil prices">','<rect width="100%" height="100%" fill="#fff"/>']
    for val in range(0, max(counts)+1, 20):
        y=Y(val); out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="#e6edf3"/><text x="{ml-8}" y="{y+4:.2f}" text-anchor="end" class="axis">{val}</text>')
    for i,c in enumerate(counts):
        x=X(i)+(W-ml-mr)/len(counts)*0.09; y=Y(c); h=H-mb-y
        out.append(f'<rect x="{x:.2f}" y="{y:.2f}" width="{bw:.2f}" height="{h:.2f}" fill="#64748b" opacity="0.82"/>')
    for i,b in enumerate(bins[:-1]):
        if i%2==0:
            out.append(f'<text x="{X(i)+(W-ml-mr)/len(counts)/2:.2f}" y="{H-mb+24}" text-anchor="middle" class="axis">{b}</text>')
    mean=statistics.mean(prices); median=statistics.median(prices)
    def Xv(v): return ml+(v/(len(counts)*binw))*(W-ml-mr)
    for v,label,color in [(mean,'mean','#d97706'),(median,'median','#0f5e9c')]:
        x=Xv(v); out.append(f'<line x1="{x:.2f}" x2="{x:.2f}" y1="{mt}" y2="{H-mb}" stroke="{color}" stroke-width="2" stroke-dasharray="5 4"/>')
        out.append(f'<text x="{x+6:.2f}" y="{mt+16 if label=="mean" else mt+34}" class="ann-sub" fill="{color}">{label} ${v:.2f}</text>')
    out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{H-mb}" y2="{H-mb}" stroke="#334155"/><line x1="{ml}" x2="{ml}" y1="{mt}" y2="{H-mb}" stroke="#334155"/>')
    out.append(f'<text x="{W/2}" y="{H-14}" text-anchor="middle" class="axis-title">USD/bbl bins</text>')
    out.append('</svg>')
    return ''.join(out)

def annual_heat(annual):
    W,H=980,230; ml,mr,mt,mb=55,25,34,42
    years=[a['year'] for a in annual]
    minv=min(a['mean'] for a in annual); maxv=max(a['mean'] for a in annual)
    cell=(W-ml-mr)/len(annual)
    def color(v):
        t=(v-minv)/(maxv-minv)
        # interpolate slate -> amber -> red
        if t<0.55:
            k=t/0.55; c1=(226,232,240); c2=(245,158,11)
        else:
            k=(t-0.55)/0.45; c1=(245,158,11); c2=(185,28,28)
        c=tuple(round(c1[i]*(1-k)+c2[i]*k) for i in range(3))
        return '#%02x%02x%02x'%c
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Annual average price heat strip">','<rect width="100%" height="100%" fill="#fff"/>']
    for i,a in enumerate(annual):
        x=ml+i*cell
        out.append(f'<rect x="{x:.2f}" y="{mt}" width="{cell+0.2:.2f}" height="76" fill="{color(a["mean"])}"/>')
        if a['year'] in [1970,1980,1990,2000,2010,2020,2026]:
            out.append(f'<text x="{x:.2f}" y="{mt+100}" text-anchor="middle" class="axis">{a["year"]}</text>')
        if a['year'] in [1970,2008,2012,2020,2022,2026]:
            out.append(f'<text x="{x+cell/2:.2f}" y="{mt-8}" text-anchor="middle" class="tiny-label">${a["mean"]:.0f}</text>')
    out.append(f'<text x="{W/2}" y="22" text-anchor="middle" class="legend">Annual average nominal price intensity: {minv:.2f} low to {maxv:.2f} high</text>')
    # legend
    lx=W-270; ly=H-42
    for i in range(80):
        v=minv+(maxv-minv)*i/79
        out.append(f'<rect x="{lx+i*2:.1f}" y="{ly}" width="2.2" height="12" fill="{color(v)}"/>')
    out.append(f'<text x="{lx-6}" y="{ly+11}" text-anchor="end" class="axis">${minv:.0f}</text><text x="{lx+166}" y="{ly+11}" class="axis">${maxv:.0f}</text>')
    out.append('</svg>')
    return ''.join(out)

