import csv, math, statistics, html
from datetime import datetime, date
from pathlib import Path
from collections import defaultdict

DATA = Path('/app/benchmark/data.csv')
OUT = Path('/app/output/final_report.html')
OUT.parent.mkdir(parents=True, exist_ok=True)

def read_rows():
    rows=[]
    with DATA.open(newline='') as f:
        for rec in csv.DictReader(f):
            d=datetime.strptime(rec['Date'], '%Y-%m-%d').date()
            rows.append({'date':d, 'price':float(rec['Crude_Oil_Price'])})
    rows.sort(key=lambda r:r['date'])
    for i,r in enumerate(rows):
        r['year']=r['date'].year
        r['decade']=(r['year']//10)*10
        if i:
            prev=rows[i-1]['price']
            r['mom_abs']=r['price']-prev
            r['mom_pct']=(r['price']/prev-1)*100
        else:
            r['mom_abs']=None; r['mom_pct']=None
        if i>=12:
            prev=rows[i-12]['price']
            r['yoy_abs']=r['price']-prev
            r['yoy_pct']=(r['price']/prev-1)*100
        else:
            r['yoy_abs']=None; r['yoy_pct']=None
    return rows

rows=read_rows()
prices=[r['price'] for r in rows]
first,last=rows[0],rows[-1]
years=(last['date']-first['date']).days/365.25
cagr=(last['price']/first['price'])**(1/years)-1

def quantile(vals, q):
    vals=sorted(vals); n=len(vals); pos=(n-1)*q; lo=math.floor(pos); hi=math.ceil(pos)
    if lo==hi: return vals[lo]
    return vals[lo]*(hi-pos)+vals[hi]*(pos-lo)

def fmt_d(d): return d.strftime('%b %Y')
def fmt_price(x): return f"${x:,.2f}"
def fmt_pct(x): return f"{x:+,.1f}%"
def esc(s): return html.escape(str(s), quote=True)

min_row=min(rows, key=lambda r:r['price'])
max_row=max(rows, key=lambda r:r['price'])
valid_m=[r for r in rows if r['mom_abs'] is not None]
valid_y=[r for r in rows if r['yoy_abs'] is not None]
max_abs_mom=max(valid_m, key=lambda r:abs(r['mom_abs']))
max_pos_mom_pct=max(valid_m, key=lambda r:r['mom_pct'])
max_neg_mom_pct=min(valid_m, key=lambda r:r['mom_pct'])
max_abs_yoy=max(valid_y, key=lambda r:abs(r['yoy_abs']))

# Groups
dec_groups=defaultdict(list)
for r in rows: dec_groups[r['decade']].append(r)
decades=[]
for dec in sorted(dec_groups):
    rs=dec_groups[dec]; ps=[r['price'] for r in rs]
    decades.append({
        'decade':dec, 'label':f"{dec}s", 'months':len(rs), 'start':rs[0]['date'], 'end':rs[-1]['date'],
        'mean':statistics.mean(ps), 'median':statistics.median(ps), 'std':statistics.stdev(ps) if len(ps)>1 else 0,
        'min':min(ps), 'max':max(ps), 'range':max(ps)-min(ps), 'first':rs[0]['price'], 'last':rs[-1]['price'],
        'change_abs':rs[-1]['price']-rs[0]['price'], 'change_pct':(rs[-1]['price']/rs[0]['price']-1)*100
    })
highest_dec=max(decades, key=lambda d:d['mean'])

ann_groups=defaultdict(list)
for r in rows: ann_groups[r['year']].append(r)
annual=[]
for y in sorted(ann_groups):
    rs=ann_groups[y]; ps=[r['price'] for r in rs]
    annual.append({'year':y,'mean':statistics.mean(ps),'std':statistics.stdev(ps) if len(ps)>1 else 0,'min':min(ps),'max':max(ps),'first':rs[0]['price'],'last':rs[-1]['price'],'months':len(rs)})
highest_annual=max(annual, key=lambda a:a['mean'])
lowest_annual=min(annual, key=lambda a:a['mean'])
most_volatile_year=max(annual, key=lambda a:a['std'])
annual_by_year={a['year']:a for a in annual}
row_by_date={r['date']:r for r in rows}
def point(d): return row_by_date[d]
def date_to_num(d): return d.toordinal()

# SVG functions
def line_chart(rows):
    W,H=1100,520; ml,mr,mt,mb=72,38,44,68
    xs=[date_to_num(r['date']) for r in rows]; xmin,xmax=min(xs),max(xs); ymin=0; ymax=140
    def X(d): return ml+(date_to_num(d)-xmin)/(xmax-xmin)*(W-ml-mr)
    def Y(v): return mt+(ymax-v)/(ymax-ymin)*(H-mt-mb)
    pts=' '.join(f"{X(r['date']):.2f},{Y(r['price']):.2f}" for r in rows)
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Monthly crude oil price line chart from 1970 to 2026"><rect width="100%" height="100%" fill="#ffffff"/>']
    for val in range(0,141,20):
        y=Y(val); out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="#e6edf3"/><text x="{ml-10}" y="{y+4:.2f}" text-anchor="end" class="axis">${val}</text>')
    for yr in [1970,1980,1990,2000,2010,2020,2026]:
        x=X(date(yr,1,1) if yr<2026 else date(2026,3,1))
        out.append(f'<line x1="{x:.2f}" x2="{x:.2f}" y1="{mt}" y2="{H-mb}" stroke="#edf2f7"/><text x="{x:.2f}" y="{H-mb+28}" text-anchor="middle" class="axis">{yr}</text>')
    out.append(f'<polyline points="{pts}" fill="none" stroke="#0f5e9c" stroke-width="2.6" stroke-linejoin="round"/>')
    roll=[]
    for i,r in enumerate(rows):
        start=max(0,i-11); avg=statistics.mean([x['price'] for x in rows[start:i+1]])
        roll.append((r['date'],avg))
    roll_pts=' '.join(f"{X(d):.2f},{Y(v):.2f}" for d,v in roll)
    out.append(f'<polyline points="{roll_pts}" fill="none" stroke="#f28e2b" stroke-width="2.0" opacity="0.9" stroke-linejoin="round"/>')
    anns=[
        (date(1974,1,1),'1974 oil shock', 'price $13.00; MoM +217.1%', 48, -42),
        (date(1979,11,1),'1979 spike', 'price $40.75', 18, -60),
        (date(1986,4,1),'1986 reset', 'sub-$12 regime', 12, 45),
        (date(2008,7,1),'Jul 2008 peak', 'all-time high $132.83', -130, -28),
        (date(2008,10,1),'Oct 2008 break', 'largest $ drop: -$26.96 MoM', -122, 60),
        (date(2014,12,1),'2014 selloff', '-$16.29 MoM', 18, 52),
        (date(2020,3,1),'COVID shock', 'largest % drop: -39.6% MoM', -160, 66),
        (date(2022,3,1),'2022 spike', '$112.40; +20.2% MoM', -116, -60),
        (date(2026,3,1),'Latest point', '$87.84', -108, -40),
    ]
    for d,title,sub,dx,dy in anns:
        if d not in row_by_date: continue
        x,y=X(d),Y(row_by_date[d]['price'])
        tx=max(ml+10,min(W-mr-170,x+dx)); ty=max(mt+18,min(H-mb-12,y+dy))
        out.append(f'<circle cx="{x:.2f}" cy="{y:.2f}" r="4.2" fill="#d62728" stroke="#fff" stroke-width="1.5"/><line x1="{x:.2f}" y1="{y:.2f}" x2="{tx:.2f}" y2="{ty-12:.2f}" stroke="#94a3b8" stroke-width="1"/><text x="{tx:.2f}" y="{ty:.2f}" class="ann-title">{esc(title)}</text><text x="{tx:.2f}" y="{ty+15:.2f}" class="ann-sub">{esc(sub)}</text>')
    out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{H-mb}" y2="{H-mb}" stroke="#334155"/><line x1="{ml}" x2="{ml}" y1="{mt}" y2="{H-mb}" stroke="#334155"/><text x="{ml}" y="24" class="legend"><tspan fill="#0f5e9c">■</tspan> Monthly price <tspan fill="#f28e2b" dx="16">■</tspan> 12-month trailing average</text><text x="{W/2}" y="{H-18}" text-anchor="middle" class="axis-title">Observation date</text><text x="18" y="{H/2}" text-anchor="middle" transform="rotate(-90 18 {H/2})" class="axis-title">USD per barrel</text></svg>')
    return ''.join(out)

def decade_chart(decades):
    W,H=900,360; ml,mr,mt,mb=64,28,34,62; ymax=90; slot=(W-ml-mr)/len(decades); barw=slot*.58
    def X(i): return ml+(i+.5)*slot
    def Y(v): return mt+(ymax-v)/ymax*(H-mt-mb)
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Decade average prices with volatility"><rect width="100%" height="100%" fill="#fff"/>']
    for val in range(0,91,15):
        y=Y(val); out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="#e6edf3"/><text x="{ml-8}" y="{y+4:.2f}" text-anchor="end" class="axis">${val}</text>')
    for i,d in enumerate(decades):
        x=X(i); y=Y(d['mean']); h=H-mb-y; color='#0f5e9c' if d['decade']!=highest_dec['decade'] else '#d97706'
        err_top=Y(min(ymax,d['mean']+d['std'])); err_bot=Y(max(0,d['mean']-d['std']))
        out.append(f'<rect x="{x-barw/2:.2f}" y="{y:.2f}" width="{barw:.2f}" height="{h:.2f}" rx="5" fill="{color}" opacity="0.88"/><line x1="{x:.2f}" x2="{x:.2f}" y1="{err_top:.2f}" y2="{err_bot:.2f}" stroke="#1f2937" stroke-width="1.4"/><line x1="{x-8:.2f}" x2="{x+8:.2f}" y1="{err_top:.2f}" y2="{err_top:.2f}" stroke="#1f2937"/><line x1="{x-8:.2f}" x2="{x+8:.2f}" y1="{err_bot:.2f}" y2="{err_bot:.2f}" stroke="#1f2937"/><text x="{x:.2f}" y="{y-8:.2f}" text-anchor="middle" class="bar-label">${d["mean"]:.1f}</text><text x="{x:.2f}" y="{H-mb+25}" text-anchor="middle" class="axis">{d["label"]}</text>')
        if d['decade']==2020: out.append(f'<text x="{x:.2f}" y="{H-mb+43}" text-anchor="middle" class="axis small">75 months</text>')
    out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{H-mb}" y2="{H-mb}" stroke="#334155"/><line x1="{ml}" x2="{ml}" y1="{mt}" y2="{H-mb}" stroke="#334155"/><text x="{W/2}" y="22" text-anchor="middle" class="legend">Bars show decade mean; whiskers show ±1 sample standard deviation</text></svg>')
    return ''.join(out)

def shock_chart(shocks):
    W,H=940,390; ml,mr,mt,mb=70,28,42,118; vmax=max(abs(s['value']) for s in shocks)*1.18
    def X(i): return ml+(i+.5)*(W-ml-mr)/len(shocks)
    def Y(v): return mt+(vmax-v)/(2*vmax)*(H-mt-mb)
    zero=Y(0); barw=(W-ml-mr)/len(shocks)*.52
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Largest absolute month-over-month price shocks"><rect width="100%" height="100%" fill="#fff"/>']
    for val in [-30,-20,-10,0,10,20,30]:
        if abs(val)<=vmax:
            y=Y(val); stroke='#334155' if val==0 else '#e6edf3'
            out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="{stroke}"/><text x="{ml-8}" y="{y+4:.2f}" text-anchor="end" class="axis">{val:+}</text>')
    for i,s in enumerate(shocks):
        x=X(i); y=Y(s['value']); h=abs(y-zero); top=min(y,zero); color='#b91c1c' if s['value']<0 else '#047857'
        label_y=top-7 if s['value']>0 else top+h+16
        out.append(f'<rect x="{x-barw/2:.2f}" y="{top:.2f}" width="{barw:.2f}" height="{h:.2f}" rx="4" fill="{color}" opacity="0.86"/><text x="{x:.2f}" y="{label_y:.2f}" text-anchor="middle" class="bar-label">{s["value"]:+.1f}</text><text x="{x:.2f}" y="{H-mb+25}" text-anchor="end" transform="rotate(-35 {x:.2f} {H-mb+25})" class="axis">{esc(s["label"])}</text>')
    out.append(f'<text x="{W/2}" y="24" text-anchor="middle" class="legend">Top absolute month-over-month changes, USD/bbl</text></svg>')
    return ''.join(out)

def histogram(prices):
    W,H=860,330; ml,mr,mt,mb=60,25,28,58; binw=10; counts=[]
    for b in range(0,150,10): counts.append(sum(1 for p in prices if b <= p < b+binw))
    counts[-1]+=sum(1 for p in prices if p>=150)
    ymax=max(counts)*1.15; slot=(W-ml-mr)/len(counts); bw=slot*.82
    def X(i): return ml+i*slot
    def Y(v): return mt+(ymax-v)/ymax*(H-mt-mb)
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Histogram of monthly crude oil prices"><rect width="100%" height="100%" fill="#fff"/>']
    step=20
    for val in range(0, max(counts)+1, step):
        y=Y(val); out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{y:.2f}" y2="{y:.2f}" stroke="#e6edf3"/><text x="{ml-8}" y="{y+4:.2f}" text-anchor="end" class="axis">{val}</text>')
    for i,c in enumerate(counts):
        x=X(i)+slot*.09; y=Y(c); h=H-mb-y
        out.append(f'<rect x="{x:.2f}" y="{y:.2f}" width="{bw:.2f}" height="{h:.2f}" fill="#64748b" opacity="0.82"/>')
    for i,b in enumerate(range(0,150,10)):
        if i%2==0: out.append(f'<text x="{X(i)+slot/2:.2f}" y="{H-mb+24}" text-anchor="middle" class="axis">{b}</text>')
    mean=statistics.mean(prices); median=statistics.median(prices)
    def Xv(v): return ml+(v/150)*(W-ml-mr)
    for v,label,color,off in [(mean,'mean','#d97706',16),(median,'median','#0f5e9c',34)]:
        x=Xv(v); out.append(f'<line x1="{x:.2f}" x2="{x:.2f}" y1="{mt}" y2="{H-mb}" stroke="{color}" stroke-width="2" stroke-dasharray="5 4"/><text x="{x+6:.2f}" y="{mt+off}" class="ann-sub" fill="{color}">{label} ${v:.2f}</text>')
    out.append(f'<line x1="{ml}" x2="{W-mr}" y1="{H-mb}" y2="{H-mb}" stroke="#334155"/><line x1="{ml}" x2="{ml}" y1="{mt}" y2="{H-mb}" stroke="#334155"/><text x="{W/2}" y="{H-14}" text-anchor="middle" class="axis-title">USD/bbl bins</text></svg>')
    return ''.join(out)

def annual_heat(annual):
    W,H=980,230; ml,mr,mt,mb=55,25,34,42; minv=min(a['mean'] for a in annual); maxv=max(a['mean'] for a in annual); cell=(W-ml-mr)/len(annual)
    def color(v):
        t=(v-minv)/(maxv-minv)
        if t<0.55:
            k=t/0.55; c1=(226,232,240); c2=(245,158,11)
        else:
            k=(t-0.55)/0.45; c1=(245,158,11); c2=(185,28,28)
        c=tuple(round(c1[i]*(1-k)+c2[i]*k) for i in range(3))
        return '#%02x%02x%02x'%c
    out=[f'<svg viewBox="0 0 {W} {H}" class="chart" role="img" aria-label="Annual average price heat strip"><rect width="100%" height="100%" fill="#fff"/>']
    for i,a in enumerate(annual):
        x=ml+i*cell; out.append(f'<rect x="{x:.2f}" y="{mt}" width="{cell+0.2:.2f}" height="76" fill="{color(a["mean"])}"/>')
        if a['year'] in [1970,1980,1990,2000,2010,2020,2026]: out.append(f'<text x="{x:.2f}" y="{mt+100}" text-anchor="middle" class="axis">{a["year"]}</text>')
        if a['year'] in [1970,2008,2012,2020,2022,2026]: out.append(f'<text x="{x+cell/2:.2f}" y="{mt-8}" text-anchor="middle" class="tiny-label">${a["mean"]:.0f}</text>')
    lx=W-270; ly=H-42
    out.append(f'<text x="{W/2}" y="22" text-anchor="middle" class="legend">Annual average nominal price intensity: {minv:.2f} low to {maxv:.2f} high</text>')
    for i in range(80):
        v=minv+(maxv-minv)*i/79; out.append(f'<rect x="{lx+i*2:.1f}" y="{ly}" width="2.2" height="12" fill="{color(v)}"/>')
    out.append(f'<text x="{lx-6}" y="{ly+11}" text-anchor="end" class="axis">${minv:.0f}</text><text x="{lx+166}" y="{ly+11}" class="axis">${maxv:.0f}</text></svg>')
    return ''.join(out)

